import{c as t,Q as r,j as s,m as o}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Reports","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports.md","filePath":"guide/reports.md","lastUpdated":null}'),a={name:"guide/reports.md"};function n(i,e,d,h,p,l){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h1><p>Monthly trends, category and merchant tables, review snapshots, and exports.</p><h2 id="what-reports-shows" tabindex="-1">What Reports shows <a class="header-anchor" href="#what-reports-shows" aria-label="Permalink to &quot;What Reports shows&quot;">​</a></h2><ul><li><strong>Monthly trends</strong> — income, expenses, and savings rate over the selectable window. Computed from <code>metrics</code>, same source as Today.</li><li><strong>Category tables</strong> — spend by category for the window, with prior-period and YTD comparisons.</li><li><strong>Merchant tables</strong> — top merchants by spend and frequency; merchant name uses the same normalization as Transactions.</li><li><strong>Review snapshots</strong> — canned review views (end-of-month, last 90 days) rendered in <code>reportWidgets</code>.</li></ul><h2 id="custom-widgets" tabindex="-1">Custom widgets <a class="header-anchor" href="#custom-widgets" aria-label="Permalink to &quot;Custom widgets&quot;">​</a></h2><p><code>repos/report_widgets</code> stores drag-ordered report widgets per user. The layout is persisted in your encrypted database; resetting it is a row delete, not a migration.</p><h2 id="exports" tabindex="-1">Exports <a class="header-anchor" href="#exports" aria-label="Permalink to &quot;Exports&quot;">​</a></h2><ul><li><strong>CSV</strong> — current Report window as CSV (streamed from the server; no third-party involved).</li><li><strong>Per-user snapshots</strong> — via <strong>Settings → Data &amp; backups</strong>, which creates an encrypted snapshot under <code>users/&lt;uuid&gt;/backups/</code>.</li></ul><h2 id="when-numbers-look-wrong" tabindex="-1">When numbers look wrong <a class="header-anchor" href="#when-numbers-look-wrong" aria-label="Permalink to &quot;When numbers look wrong&quot;">​</a></h2><p>Check the scope first:</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th></tr></thead><tbody><tr><td>One month spikes</td><td>Large transfer not linked as transfer — it counts as expense then income</td></tr><tr><td>Category total disagrees with Budget</td><td>Budget shows <em>budgeted</em> vs <em>spent</em>; Report shows <em>actuals</em> for the window</td></tr><tr><td>Net worth jumps</td><td>An account’s opening balance or a manual balance entry</td></tr></tbody></table><p>Ask the Copilot “Explain this report number” — the metric inspector shows definition, inputs, exclusions, and assumptions for that figure.</p><p>See also: <a href="/FinSight/guide/budget">Budget</a>, <a href="/FinSight/guide/transactions">Transactions</a>.</p>',13)])])}const m=t(a,[["render",n]]);export{u as __pageData,m as default};
